using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using ModelContextProtocol;

var builder = Host.CreateApplicationBuilder(args);

builder.Services.AddHttpClient("WeatherApi", client =>
{
    client.BaseAddress = new Uri("https://api.weather.example.com/");
    client.DefaultRequestHeaders.Add("Accept", "application/json");
});

builder.Services
    .AddMcpServer()
    .WithStdioServerTransport()
    .WithToolsFromAssembly();

await builder.Build().RunAsync();

using System.ComponentModel;
using System.Net.Http.Json;
using ModelContextProtocol.Server;

namespace MyMcpServer.Tools;

[McpServerToolType]
public sealed class WeatherTools
{
    private readonly IHttpClientFactory _httpClientFactory;

    public WeatherTools(IHttpClientFactory httpClientFactory)
    {
        _httpClientFactory = httpClientFactory;
    }

    [McpServerTool, Description("Get the current weather forecast for a city.")]
    public async Task<string> GetForecast(
        [Description("City name, e.g. 'Seattle'")] string city,
        CancellationToken cancellationToken = default)
    {
        using var client = _httpClientFactory.CreateClient("WeatherApi");

        var forecast = await client.GetFromJsonAsync<WeatherResponse>(
            $"forecast?city={Uri.EscapeDataString(city)}",
            cancellationToken);

        return forecast is not null
            ? $"{forecast.City}: {forecast.Temperature}°F, {forecast.Condition}"
            : "Forecast unavailable.";
    }

    [McpServerTool, Description("Get weather alerts for a US state.")]
    public async Task<string> GetAlerts(
        [Description("Two-letter US state code, e.g. 'WA'")] string state,
        CancellationToken cancellationToken = default)
    {
        using var client = _httpClientFactory.CreateClient("WeatherApi");

        var alerts = await client.GetFromJsonAsync<AlertResponse[]>(
            $"alerts?state={Uri.EscapeDataString(state)}",
            cancellationToken);

        if (alerts is null || alerts.Length == 0)
            return $"No active alerts for {state}.";

        return string.Join("\n", alerts.Select(a => $"⚠️ {a.Event}: {a.Headline}"));
    }

    private record WeatherResponse(string City, double Temperature, string Condition);
    private record AlertResponse(string Event, string Headline);
}

